import{describe,it,expect}from"vitest";import{BHARAT_RATNA_RECIPIENTS,filterRecipients,getBharatRatnaStats}from"../../frontend/bharat-ratna-gallery/bharat-ratna-gallery.js";describe("Bharat Ratna Recipients Dataset Integrity",()=>{it("contains comprehensive recipient records from 1954 to 2024",()=>{expect(BHARAT_RATNA_RECIPIENTS.length).toBeGreaterThanOrEqual(45);const e=BHARAT_RATNA_RECIPIENTS.map(e=>e.year);expect(Math.min(...e)).toBe(1954),expect(Math.max(...e)).toBe(2024)}),it("every recipient contains required properties (id, name, year, decade, category, portrait, contribution, biography)",()=>{BHARAT_RATNA_RECIPIENTS.forEach((e,t)=>{expect(e,`Recipient at index ${t} missing id`).toHaveProperty("id"),expect(e,`Recipient at index ${t} missing name`).toHaveProperty("name"),expect(e,`Recipient at index ${t} missing year`).toHaveProperty("year"),expect(e,`Recipient at index ${t} missing decade`).toHaveProperty("decade"),expect(e,`Recipient at index ${t} missing category`).toHaveProperty("category"),expect(e,`Recipient at index ${t} missing portrait`).toHaveProperty("portrait"),expect(e,`Recipient at index ${t} missing contribution`).toHaveProperty("contribution"),expect(e,`Recipient at index ${t} missing biography`).toHaveProperty("biography"),expect(e,`Recipient at index ${t} missing posthumous`).toHaveProperty("posthumous"),expect(typeof e.name).toBe("string"),expect(e.name.trim().length).toBeGreaterThan(0),expect(typeof e.contribution).toBe("string"),expect(e.contribution.trim().length).toBeGreaterThan(0),expect(typeof e.portrait).toBe("string"),expect(e.portrait.trim().length).toBeGreaterThan(0)})}),it("maintains objective, neutral, and educational tone",()=>{const e=["corrupt","fraudulent","useless","illegal"];BHARAT_RATNA_RECIPIENTS.forEach(t=>{const a=`${t.name} ${t.contribution} ${t.biography}`.toLowerCase();e.forEach(e=>{expect(a).not.toContain(e)})})})}),describe("Bharat Ratna Gallery Helper Functions",()=>{it("filters recipients by category correctly",()=>{const e=filterRecipients(BHARAT_RATNA_RECIPIENTS,"Science & Tech","all","");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.category).toBe("Science & Tech"));const t=filterRecipients(BHARAT_RATNA_RECIPIENTS,"Sports","all","");expect(t.length).toBe(1),expect(t[0].name).toBe("Sachin Tendulkar")}),it("filters recipients by decade correctly",()=>{const e=filterRecipients(BHARAT_RATNA_RECIPIENTS,"all","1950s","");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.decade).toBe("1950s"));const t=filterRecipients(BHARAT_RATNA_RECIPIENTS,"all","2020s","");expect(t.length).toBe(5),t.forEach(e=>expect(e.decade).toBe("2020s"))}),it("searches recipients by keyword query",()=>{const e=filterRecipients(BHARAT_RATNA_RECIPIENTS,"all","all","Abdul Kalam");expect(e.length).toBe(1),expect(e[0].name).toContain("Abdul Kalam");const t=filterRecipients(BHARAT_RATNA_RECIPIENTS,"all","all","Mangeshkar");expect(t.length).toBe(1),expect(t[0].name).toContain("Lata Mangeshkar")}),it("calculates dashboard summary statistics accurately",()=>{const e=getBharatRatnaStats(BHARAT_RATNA_RECIPIENTS);expect(e.totalRecipients).toBeGreaterThanOrEqual(45),expect(e.firstAwardYear).toBe(1954),expect(e.latestAwardYear).toBe(2024),expect(e.posthumousCount).toBeGreaterThan(0)})});